@Bean
@Order(2)
public SecurityFilterChain webSecurityFilterChain(HttpSecurity http,
                                                  ClientRegistrationRepository clientRegistrationRepository) throws Exception {
    String viewRole = properties.viewRole();
    String manageRole = properties.manageRole();
    // keep the saved-request redirect but drop Spring Security's "?continue" marker from the URL
    HttpSessionRequestCache requestCache = new HttpSessionRequestCache();
    requestCache.setMatchingRequestParameterName(null);
    http
        .requestCache(cache -> cache.requestCache(requestCache))
        .authorizeHttpRequests(auth -> auth
            .requestMatchers("/css/**", "/js/**", "/img/**", "/favicon.ico", "/error",
                             "/logged-out", "/login-error", "/oauth2/**", "/login/**",
                             "/actuator/health", "/actuator/health/**", "/actuator/info").permitAll()
            .requestMatchers("/", "/access-denied", "/me").authenticated()
            .requestMatchers(HttpMethod.GET, "/**").hasRole(viewRole)
            .anyRequest().hasRole(manageRole))
        .oauth2Login(login -> login
            .loginPage("/oauth2/authorization/" + REGISTRATION_ID)
            .userInfoEndpoint(userInfo -> userInfo.userAuthoritiesMapper(keycloakAuthoritiesMapper()))
            .successHandler(loginSuccessHandler)
            .failureHandler(loginFailureHandler))
        .logout(logout -> logout
            .logoutSuccessHandler(oidcLogoutSuccessHandler(clientRegistrationRepository))
            .invalidateHttpSession(true)
            .clearAuthentication(true))
        .exceptionHandling(ex -> ex.accessDeniedPage("/access-denied"));
    return http.build();
}

/** Maps the "roles" claim of the ID token / userinfo to ROLE_* authorities. */
@Bean
public GrantedAuthoritiesMapper keycloakAuthoritiesMapper() {
    return authorities -> {
        Set<GrantedAuthority> mapped = new HashSet<>(authorities);
        for (GrantedAuthority authority : authorities) {
            if (authority instanceof OidcUserAuthority oidc) {
                mapped.addAll(KeycloakRoles.fromClaims(oidc.getIdToken().getClaims()));
                if (oidc.getUserInfo() != null) {
                    mapped.addAll(KeycloakRoles.fromClaims(oidc.getUserInfo().getClaims()));
                }
            } else if (authority instanceof OAuth2UserAuthority oauth2) {
                mapped.addAll(KeycloakRoles.fromClaims(oauth2.getAttributes()));
            }
        }
        return mapped;
    };
}
